export const handleAddRecord = async (taskData, contacts, isAddDialogVisible) => {
  try {
    const dialog = DialogUtility.confirm({
      title: 'Add New Task',
      content: 'Are you sure you want to add this task?',
      okButton: {
        text: 'Yes',
        click: async () => {
          try {
            const retData = await createContact(taskData);
            taskData.id = retData.id;
            contacts.value.push({ ...taskData });
            // filterByType(taskMode.value);
            alert('Task added successfully!');
            //isAddDialogVisible.value = false;
            dialog.hide();
          } catch (error) {
            alert('Error adding task: ' + error.message);
          }
        }
      },
      cancelButton: {
        text: 'No',
        click: () => {
          dialog.hide();
        }
      }
    });
  } catch (error) {
    console.error('Error adding task:', error);
  }
};

export const loadByProject = async (projectFilter, locationFilter,dialedDateFilter,ratingFilter, contacts) => {
  try {
    const loadedContacts = await loadByProjectFunc(
      projectFilter,
      locationFilter,
      dialedDateFilter,
      ratingFilter,
      contacts.value,
      new Date().toLocaleDateString('en-GB', { day: '2-digit', month: '2-digit', year: 'numeric' }),
      fetchContactsRatingQuery
    );
    contacts.value = loadedContacts;
  } catch (error) {
    console.error('Error loading contacts:', error);
  }
};

export async function loadByProjectFunc(projectFilter, locationFilter,dialedDateFilter,ratingFilter, contacts, importDate, gql) {
  try {
    // Initialize filters object
    const variables = { filters: {} };

    // Apply project filter
    if (dialedDateFilter.value !== null) {
      variables.filters.dialedDate = { gte: formatDateForStrapi(dialedDateFilter.value) };
    }

    if (projectFilter !== 'All') {
      variables.filters.project = { eq: projectFilter };
    }

    if (locationFilter !== 'All') {
      variables.filters.location = { eq: locationFilter };
    }

    // Apply rating filter
    if (ratingFilter !== null && ratingFilter !== undefined) {
      variables.filters.rating = { gte: parseInt(ratingFilter, 10) };
    }

    // Debugging: Log the variables being sent
    console.log("Variables being sent to the query:", variables);

    // Fetch data from Strapi

    
    const { data, error } = await client.query({
      query: gql,
      variables,
      fetchPolicy: 'network-only',
    });

    // Check for errors in the response
    if (error) {
      console.error("GraphQL Error:", error);
      throw new Error("GraphQL query failed");
    }

    
    // Debugging: Log the data received
    console.log("Data received from the query:", data);

    // Clear existing contacts
    contacts.length = 0;

    // Process and populate contacts
    data.leads.data.forEach(lead => {
      if (!lead.attributes.project) return; // Skip leads without a project
      contacts.push({
        id: lead.id,
        location:lead.attributes.location||'',
        coBroked: lead.attributes.coBroked,
        coBrokedIcon: lead.attributes.coBroked ? "🤝" : "🤗",
        no: lead.attributes.no,
        user: lead.attributes.user || 'Unassigned',
        assignee: lead.attributes.assignee || 'Unassigned',
        name: lead.attributes.name || '',
        phoneNumber: formatPhoneNumber2(lead.attributes.phoneNumber) || '',
        project: lead.attributes.project || '',
        occupation: lead.attributes.occupation || '',
        status: lead.attributes.status || '',
        phoneId: lead.attributes.phoneId || '',
        interaction: lead.attributes.interaction || 'No interaction',
        lastCall: convertYMD2DMY(lead.attributes.lastCall) || null,
        nextCall: convertYMD2DMY(lead.attributes.nextCall) || null,
        called: lead.attributes.called || 0,
        rating: lead.attributes.rating || 0,
        dialedDate: convertYMD2DMY(lead.attributes.dialedDate) || null,
        sourceDate: convertYMD2DMY(lead.attributes.sourceDate) || null,
        contacted: lead.attributes.contacted || 0,
        language: lead.attributes.language || '',
        message: lead.attributes.message || '',
        doc: lead.attributes.doc || '',
        source: lead.attributes.source || '',
        requestType: lead.attributes.requestType,
        requestColor: getCardColor(lead.attributes.requestType),
        process: lead.attributes.process || '',
        stage: lead.attributes.stage || 'Qualify',
        stageEmoji: getStageEmoji(lead.attributes.stage),
        task: lead.attributes.task || '',
        delegate: lead.attributes.delegate || '',
        address: lead.attributes.address || '',
        advUrl: lead.attributes.advUrl || '',
        advUrlDate: lead.attributes.advUrlDate || '',
        facebookUrl: lead.attributes.facebookUrl || '',
        notionUrl: lead.attributes.notionUrl || '',
        actions: lead.attributes.action,
        documents: lead.attributes.document,
        advertisements: lead.attributes.advertisement,
        edit: false,
        editField: '',
        updatedAt: importDate,
        info: lead.attributes.info || '',
        remark: lead.attributes.remark || '',
        leaseFrom: lead.attributes.leaseFrom,
        leaseTo: lead.attributes.leaseTo,
        monthlyRental: lead.attributes.monthlyRental,
        builtUpArea: lead.attributes.builtUpArea,
        landArea: lead.attributes.landArea,
        dealCount: lead.attributes.dealCount,
        dateBuilt: lead.attributes.dateBuilt,
        brickzPrice: lead.attributes.brickzPrice,
        askingPrice: lead.attributes.askingPrice,
        marketPrice: lead.attributes.marketPrice,
        bankerEvaluation: lead.attributes.bankerEvaluation,
        carPark: lead.attributes.carPark,
      });
    });
  } catch (error) {
    console.error("An error occurred:", error);
    alert("An error occurred: " + error.message);
  }

  return contacts;
}

