export function formatPhoneNumber2(phone) {
  if (!phone) return '';
  if (phone[0] === ":") return '';

  // Remove spaces and dashes
  const sanitizedPhone = phone.replace(/[\s-]/g, '');

  // Check if the number is already in a valid international format
  if (sanitizedPhone.startsWith('+60')) {
    return sanitizedPhone; // If it already starts with +60, return as is
  }

  // Try parsing the phone number assuming a default region of 'MY' (Malaysia)
  const phoneData = parsePhoneNumberFromString(sanitizedPhone, 'MY');

  if (phoneData && phoneData.isValid()) {
    // Format the phone number in international format (it will include the correct country code)
    return phoneData.formatInternational();
  } else {
    // If parsing fails or if it's a local Malaysian number without +60
    if (!sanitizedPhone.startsWith('60')) {
      // Add +60 only if it’s not already prefixed with '60'
      return `+60${sanitizedPhone}`;
    } else {
      // If it already starts with '60' (without the '+'), just add the '+'
      return `+${sanitizedPhone}`;
    }
  }
}

export function convertYMD2DMY(dateString) {
  // Check if dateString is valid
  if (!dateString) return '';

  // Parse the date string to a Date object
  const date = new Date(dateString);

  // Check if the date is valid
  if (isNaN(date.getTime()) || (date.getFullYear() === 1900 && date.getMonth() === 0 && date.getDate() === 1)) {
    return '';
  }

  // Format the date as DD/MM/YYYY
  const dayStr = String(date.getDate()).padStart(2, '0');
  const monthStr = String(date.getMonth() + 1).padStart(2, '0'); // Months are zero-based
  const yearStr = date.getFullYear();

  return `${dayStr}/${monthStr}/${yearStr}`;
}

function removeTypename(data) {
  if (Array.isArray(data)) {
    return data.map(removeTypename);
  }
  if (data !== null && typeof data === 'object') {
    const { __typename, ...rest } = data; // Destructure to remove __typename
    return Object.fromEntries(
      Object.entries(rest).map(([key, value]) => [key, removeTypename(value)])
    );
  }
  return data;
}

function getCurrentDateForStrapi() {
  const currentDate = new Date();
  return currentDate.toISOString(); // Converts to ISO 8601 format
}

export function formatDateForStrapi(date) {
  if (!date) return null; // Handle empty values

  let parsedDate = new Date(date);

  if (isNaN(parsedDate.getTime())) {
      console.error("Invalid date format:", date);
      return null;
  }

  // Ensure the date is not earlier than 1900-01-01
  const minDate = new Date("1900-01-01");
  if (parsedDate < minDate) {
      return null; // Set to null if before 1900
  }

  return parsedDate.toISOString(); // Returns "YYYY-MM-DDTHH:mm:ss.sssZ"
}


