<template>
  <div v-if="visible" class="dialog-container">
    <div class="dialog-header">
      <h2>Add New Task</h2>
      <button class="close-btn" @click="closeDialog">×</button>
    </div>
    <div class="dialog-content">
      <form @submit.prevent="handleSave">
        <div class="form-group">
          <label for="name">Name:</label>
          <input id="name" v-model="taskData.name" placeholder="Name" class="form-input" />
        </div>
        <div class="form-group">
          <label for="phone">Phone:</label>
          <input id="phone" v-model="taskData.phoneNumber" placeholder="Phone Number" class="form-input" />
        </div>
        <div class="form-group">
          <label for="requestType">Request Type:</label>
          <select id="requestType" v-model="taskData.requestType" class="form-select">
            <option v-for="type in requestTypes" :key="type.text" :value="type.text">{{ type.text }}</option>
          </select>
        </div>
        <div class="form-group">
          <label for="stage">Stage:</label>
          <select id="stage" v-model="taskData.stage" class="form-select">
            <option v-for="stage in stages" :key="stage" :value="stage">{{ stage }}</option>
          </select>
        </div>
        <div class="form-group">
          <label for="assignee">Assignee:</label>
          <select id="assignee" v-model="taskData.assignee" class="form-select">
            <option v-for="assignee in assignees" :key="assignee" :value="assignee">{{ assignee }}</option>
          </select>
        </div>
        <div class="form-group">
          <label for="rating">Rating:</label>
          <select id="rating" v-model="taskData.rating" class="form-select">
            <option v-for="rating in ratings" :key="rating" :value="rating">{{ rating }}</option>
          </select>
        </div>
        <div class="form-group">
          <label for="coBroked">Co-Broked:</label>
          <input type="checkbox" id="coBroked" v-model="taskData.coBroked" class="form-checkbox" />
        </div>
        <div class="form-group">
          <label for="interaction">Interaction:</label>
          <textarea id="interaction" v-model="taskData.interaction" placeholder="Interaction details..." class="form-textarea"></textarea>
        </div>
        <div class="form-group buttons">
          <button type="submit" class="btn btn-primary">💾 Save</button>
          <button type="button" @click="closeDialog" class="btn">Close</button>
        </div>
      </form>
    </div>
  </div>
</template>

<script setup>
import { ref, defineProps, defineEmits, watch } from 'vue';

const props = defineProps({
  visible: {
    type: Boolean,
    required: true
  },
  requestType: {
    type: String,
    default: 'task' // Default value if not provided
  }
});

const emit = defineEmits(['close', 'save']);

const taskData = ref({
  name: '',
  phoneNumber: '',
  requestType: props.requestType, // Initialize with the passed requestType
  assignee: 'Unassigned',
  rating: 4,
  interaction: '',
  stage: 'Qualify',
  project: 'task',
  coBroked: false
});

// Watch for changes in the `requestType` prop and update `taskData.requestType`
watch(
  () => props.requestType,
  (newRequestType) => {
    taskData.value.requestType = newRequestType;
  }
);

const requestTypes = [
  { text: "buyer" }, 
  { text: "seller" }, 
  { text: "rent" }, 
  { text: "lease" }, 
  { text: "project_buyer" }, 
  { text: "project_seller" }, 
  { text: "task" }
];

const assignees = ["Alyssa", "Ashton", "Alvin", "Unassigned"];
const ratings = [0, 1, 2, 3, 4, 5, 6, 7];
const stages = [
  "Advertisement", "Collect", "Closing", "Done", "Exclusive", "Follow_up",
  "Pending", "Photo", "Prepare", "Qualify", "Reject", "Research",
  "Review", "Schedule", "Screening", "Share", "Signing", "Visit",
  "iProperty", "Mudah", "Facebook", "Signage"
];

const generateRandomString = () => {
  return Math.random().toString(36).substring(2, 8).toUpperCase();
};

const resetForm = () => {
  taskData.value = {
    name: 'alvin',
    phoneNumber: generateRandomString(),
    requestType: props.requestType, // Reset with the current requestType
    assignee: 'Unassigned',
    rating: 4,
    interaction: '',
    stage: 'Qualify',
    project: 'task',
    coBroked: false
  };
};

const closeDialog = () => {
  resetForm();
  emit('close');
};

const handleSave = () => {
  emit('save', { ...taskData.value });
};
</script>

<style scoped>
.dialog-container {
  position: fixed;
  top: 50%;
  left: 50%;
  transform: translate(-50%, -50%);
  width: 600px;
  height: 600px;
  background-color: white;
  border: 1px solid #ccc;
  border-radius: 8px;
  box-shadow: 0 4px 8px rgba(0, 0, 0, 0.1);
  z-index: 1000;
  overflow: auto;
}

.dialog-header {
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: 10px;
  background-color: #f0f0f0;
  border-bottom: 1px solid #ccc;
}

.close-btn {
  background: none;
  border: none;
  font-size: 24px;
  cursor: pointer;
}

.dialog-content {
  padding: 20px;
}

.form-group {
  margin-bottom: 15px;
}

.form-input, .form-select, .form-textarea {
  width: 100%;
  padding: 4px;
  border: 1px solid #ccc;
  border-radius: 4px;
}

.form-textarea {
  height: 100px;
  resize: vertical;
}

.form-checkbox {
  margin-left: 10px;
}

.btn {
  padding: 8px 16px;
  border-radius: 4px;
  cursor: pointer;
  margin-right: 10px;
}

.btn-primary {
  background-color: #4CAF50;
  color: white;
  border: none;
}

.btn-primary:hover {
  background-color: #45a049;
}

.buttons {
  display: flex;
  justify-content: flex-end;
}
</style>