import { DialogUtility } from '@syncfusion/ej2-popups';

const closest = (element, selector) => {
  let el = element;
  while (el) {
    if (el.matches && el.matches(selector)) {
      return el;
    }
    el = el.parentElement;
  }
  return null;
};

