export const useKanbanHandlers = () => {
  const handleDataBound = () => {
    const headerEle = document.querySelector('.e-header-row');
    if (!headerEle) return;

    headerEle.addEventListener('dblclick', (e) => {
      const target = closest(e.target, '.e-header-cells');
      if (!target) return;

      const headerText = target.querySelector('.e-header-text')?.innerText;
      const content = getHeaderContent(headerText);

      DialogUtility.alert({
        title: 'Header Info',
        content: content.replaceAll('..', '<br>'),
        showCloseIcon: true,
        closeOnEscape: true,
        animationSettings: { effect: 'Zoom' }
      });
    });
  };

  return {
    handleDataBound
  };
};