<script setup>
import { ref, onMounted } from 'vue'
import axios from 'axios'

const title = ref('')
const description = ref('')
const date = ref('')
const time = ref('')
const reminderTime = ref('30') // Default 30 minutes before

const reminderOptions = [
  { value: '0', label: 'At time of event' },
  { value: '5', label: '5 minutes before' },
  { value: '15', label: '15 minutes before' },
  { value: '30', label: '30 minutes before' },
  { value: '60', label: '1 hour before' },
  { value: '1440', label: '1 day before' }
]

const isLoading = ref(false)
const error = ref(null)
const success = ref(false)

const createEvent = async () => {
  try {
    isLoading.value = true
    error.value = null
    success.value = false

    // Combine date and time
    const startDateTime = new Date(`${date.value}T${time.value}`)
    
    // Calculate reminder time
    const reminderDateTime = new Date(startDateTime.getTime() - (reminderTime.value * 60 * 1000))

    // This is where you would normally make the API call to Google Calendar
    // You'll need to implement the actual Google Calendar API integration
    // This is just a placeholder structure
    const eventData = {
      summary: title.value,
      description: description.value,
      start: {
        dateTime: startDateTime.toISOString(),
        timeZone: Intl.DateTimeFormat().resolvedOptions().timeZone
      },
      end: {
        dateTime: new Date(startDateTime.getTime() + (60 * 60 * 1000)).toISOString(), // Default 1 hour duration
        timeZone: Intl.DateTimeFormat().resolvedOptions().timeZone
      },
      reminders: {
        useDefault: false,
        overrides: [
          { method: 'popup', minutes: parseInt(reminderTime.value) }
        ]
      }
    }

    // Placeholder for API call
    const response = await axios.post('YOUR_BACKEND_ENDPOINT/calendar/events', eventData)
    console.log('Event data to be sent:', eventData)
    
    success.value = true
    clearForm()
  } catch (e) {
    error.value = 'Failed to create event. Please try again.'
    console.error('Error creating event:', e)
  } finally {
    isLoading.value = false
  }
}

const clearForm = () => {
  title.value = ''
  description.value = ''
  date.value = ''
  time.value = ''
  reminderTime.value = '30'
}

// Get today's date in YYYY-MM-DD format for min attribute
const today = new Date().toISOString().split('T')[0]
</script>

<template>
  <div class="calendar-scheduler">
    <h2 class="text-2xl font-bold mb-4">Schedule Event</h2>
    
    <form @submit.prevent="createEvent" class="space-y-4">
      <div class="form-group">
        <label for="title" class="block mb-1">Event Title *</label>
        <input
          id="title"
          v-model="title"
          type="text"
          required
          class="w-full p-2 border rounded"
          placeholder="Enter event title"
        >
      </div>

      <div class="form-group">
        <label for="description" class="block mb-1">Description</label>
        <textarea
          id="description"
          v-model="description"
          class="w-full p-2 border rounded"
          rows="3"
          placeholder="Enter event description"
        ></textarea>
      </div>

      <div class="grid grid-cols-2 gap-4">
        <div class="form-group">
          <label for="date" class="block mb-1">Date *</label>
          <input
            id="date"
            v-model="date"
            type="date"
            required
            :min="today"
            class="w-full p-2 border rounded"
          >
        </div>

        <div class="form-group">
          <label for="time" class="block mb-1">Time *</label>
          <input
            id="time"
            v-model="time"
            type="time"
            required
            class="w-full p-2 border rounded"
          >
        </div>
      </div>

      <div class="form-group">
        <label for="reminder" class="block mb-1">Reminder</label>
        <select
          id="reminder"
          v-model="reminderTime"
          class="w-full p-2 border rounded"
        >
          <option
            v-for="option in reminderOptions"
            :key="option.value"
            :value="option.value"
          >
            {{ option.label }}
          </option>
        </select>
      </div>

      <div class="mt-6">
        <button
          type="submit"
          :disabled="isLoading"
          class="bg-blue-500 text-white px-4 py-2 rounded hover:bg-blue-600 disabled:opacity-50"
        >
          {{ isLoading ? 'Creating...' : 'Create Event' }}
        </button>
      </div>

      <div v-if="error" class="text-red-500 mt-2">
        {{ error }}
      </div>

      <div v-if="success" class="text-green-500 mt-2">
        Event created successfully!
      </div>
    </form>
  </div>
</template>

<style scoped>
.calendar-scheduler {
  max-width: 600px;
  margin: 0 auto;
  padding: 1rem;
}

.form-group {
  margin-bottom: 1rem;
}

input[type="text"],
input[type="date"],
input[type="time"],
textarea,
select {
  width: 100%;
  padding: 0.5rem;
  border: 1px solid #ddd;
  border-radius: 0.25rem;
}

label {
  font-weight: 500;
}
</style>