<template>
  <div class="dialing-performance">
    <div>
      <v-select 
        v-model="selectedYear" 
        :items="years" 
        label="Year" 
        @change="fetchDialingData"
        class="ma-2"
      ></v-select>

      <!-- <v-select 
        v-model="selectedMonth" 
        :items="[{value: '', text: 'All'}, ...months.map(m => ({value: m.value, text: m.label}))]" 
        label="Month" 
        @change="fetchDialingData"
        class="ma-2"
      ></v-select> -->

      <v-select
  v-model="selectedMonth"
  :items="[{value: '', text: 'All'}, ...months.map(m => ({value: m.value, text: m.label}))]" 
  item-title="text" 
  item-value="value"
 
  label="Month"
  @change="fetchDialingData"
  class="ma-2"
></v-select>

      <v-checkbox 
        v-model="showAssignee" 
        label="Show Assignee" 
        class="ma-2"
      ></v-checkbox>
      
      <v-btn @click="printPDF" class="ma-2">Print PDF</v-btn>
    </div>

    <v-alert v-if="loading" type="info" class="mb-4">Loading dialing data...</v-alert>
    <v-alert v-else-if="error" type="error" class="mb-4">{{ error }}</v-alert>
    <div v-else>
      <h1>Dialing Performance</h1>
      <p>Total Dials: {{ totalDials }}</p>
      <p>Total Records Retrieved: {{ totalRecords }}</p>
      <p>Total Records Fetched: {{ totalRecordsFetch }}</p>
      <v-data-table
        :headers="headers"
        :items="tableItems"
        dense
        :footer-props="{
          itemsPerPageOptions: [0], // Show footer without pagination controls
          showFirstLastPage: false, // Hide first/last page buttons
          disablePagination: true,  // Disable pagination
          itemsPerPageText: 'Total:'
        }"
      >
        <template v-slot:item.date="{ item }">
          <span :rowspan="Object.keys(item.projects).length">{{ item.date }}</span>
        </template>
        <template v-slot:item.project="{ item }">
          <span>{{ item.project }}</span>
        </template>
        <template v-slot:item.assignee="{ item }">
          <span v-if="showAssignee">{{ item.assignee || 'N/A' }}</span>
        </template>
      </v-data-table>

      <!-- Custom Footer -->
      <div v-if="tableItems.length > 0">
        <table class="v-data-footer">
          <tr>
            <!-- Empty cells for non-total columns -->
            <td v-for="(header, index) in headers" :key="index" :colspan="index === 0 ? headers.length - 4 : null">
              <span v-if="index === 0">Total:</span>
            </td>
            <td>{{ calculateTotal('totalDials', tableItems) }}</td>
            <td>{{ calculateTotal('totalLeads', tableItems) }}</td>
            <td>{{ calculateTotal('totalFuture', tableItems) }}</td>
            <td>{{ calculateTotal('totalFollowUps', tableItems) }}</td>
          </tr>
        </table>
      </div>
    </div>
  </div>
</template>

<script>
import { gql } from '@apollo/client/core';
import client from '../apollo-client';
import jsPDF from 'jspdf';
import 'jspdf-autotable';
import { ref, computed, watch, onMounted } from 'vue';
import { formatDateForStrapi } from '../utils/vgraphql';

export default {
  name: 'DialingPerformanceList',
  setup() {
    const dialStats = ref({});
    const loading = ref(true);
    const error = ref(null);
    const selectedYear = ref(new Date().getFullYear());
    const selectedMonth = ref('');
    const showAssignee = ref(false);

    const years = Array.from({ length: 5 }, (_, i) => new Date().getFullYear() - i);
    const months = [
      { value: '01', label: 'January' },
      { value: '02', label: 'February' },
      { value: '03', label: 'March' },
      { value: '04', label: 'April' },
      { value: '05', label: 'May' },
      { value: '06', label: 'June' },
      { value: '07', label: 'July' },
      { value: '08', label: 'August' },
      { value: '09', label: 'September' },
      { value: '10', label: 'October' },
      { value: '11', label: 'November' },
      { value: '12', label: 'December' }
    ];

    const headers = computed(() => [
      { text: 'Date', title:'Date',value: 'date', sortable: false },
      { text: 'Project', title:'Project', value: 'project' },
      ...(showAssignee.value ? [{ text: 'Assignee', value: 'assignee', sortable: false }] : []),
      { text: 'Total Dials', title:'Total Dials', value: 'totalDials' },
      { text: 'Total Leads', title:'Total Leads', value: 'totalLeads' },
      { text: 'Total Future',  title:'Total Future',value: 'totalFuture' },
      { text: 'Total Follow-ups', title:'Total Follow-ups', value: 'totalFollowUps' }
    ]);

    const filteredDialStats = computed(() => {
      return Object.fromEntries(
        Object.entries(dialStats.value).filter(([date]) => {
          const [year, month] = date.split('-');
          return (
            year === selectedYear.value.toString() &&
            (selectedMonth.value === '' || month === selectedMonth.value)
          );
        })
      );
    });

    const totalDials = computed(() => {
      let total = 0;
      for (const projects of Object.values(filteredDialStats.value)) {
        for (const entry of Object.values(projects)) {
          total += entry.totalDials;
        }
      }
      return total;
    });

    const totalRecordsFetch = computed(() => {
      return dialStats.value.totalRecordsFetched || 0;
    });

    const totalRecords = computed(() => {
      return dialStats.value.totalRecords || 0;
    });

    const calculateTotal = (column, items) => {
      return items.reduce((total, item) => total + (item[column] || 0), 0);
    };

    const tableItems = computed(() => {
      let items = [];
      for (const [date, projects] of Object.entries(filteredDialStats.value)) {
        for (const [project, entry] of Object.entries(projects)) {
          items.push({
            date: new Date(date), // Convert string to Date object for sorting
            project,
            assignee: showAssignee.value ? entry.assignee : undefined,
            totalDials: entry.totalDials,
            totalLeads: entry.totalLeads,
            totalFuture: entry.totalFuture,
            totalFollowUps: entry.totalFollowUps,
            projects // Keep the projects for rowspan logic
          });
        }
      }

      // Sort items by date in ascending order (oldest first)
      items.sort((a, b) => a.date - b.date);

      // Convert Date back to string for display
      return items.map(item => ({ ...item, date: item.date.toISOString().split('T')[0] }));
    });

    const fetchDialingData = async () => {
      loading.value = true;
      error.value = null;

      const startDate = selectedMonth.value ? `${selectedYear.value}-${selectedMonth.value}-01` : `${selectedYear.value}-01-01`;
      const endDate = selectedMonth.value ? `${selectedYear.value}-${selectedMonth.value}-31` : `${selectedYear.value}-12-31`;

      let fstartDate = formatDateForStrapi(startDate);
      let fendDate = formatDateForStrapi(endDate);

      try {
        const { data } = await client.query({
          query: gql`
            query GetDials {
              leads(
                pagination: { limit: 2000 },
                sort: ["project", "dialedDate"],
                filters: { 
                  dialedDate: { 
                    gte: "${fstartDate}", 
                    lte: "${fendDate}" 
                  }
                }
              ) {
                data {
                  attributes {
                    requestType
                    dialedDate
                    assignee
                    project
                    rating
                  }
                }
                meta {
                  pagination {
                    total
                  }
                }
              }
            }
          `,
          fetchPolicy: 'no-cache',
        });

        dialStats.value = {
          totalRecords: data.leads.meta.pagination.total,  
          totalRecordsFetched: data.leads.data.length,    
          ...data.leads.data.reduce((acc, lead) => {
            let { dialedDate, project, rating, requestType, assignee } = lead.attributes;
            project = project || 'Unknown';
            assignee = assignee || 'N/A';

            if (dialedDate) {
              let parsedDate = new Date(dialedDate);
              if (!isNaN(parsedDate)) {
                let date = parsedDate.toISOString().split('T')[0];
                acc[date] = acc[date] || {};
                acc[date][project] = acc[date][project] || {
                  assignee,
                  totalDials: 0,
                  totalLeads: 0,
                  totalFuture: 0,
                  totalFollowUps: 0,
                };
                acc[date][project].totalDials += 1;
                if (rating > 3) {
                  acc[date][project].totalLeads += 1;
                } else if (rating === 3 || requestType === 'tenanted' || requestType === 'rent') {
                  acc[date][project].totalFuture += 1;
                } else {
                  acc[date][project].totalFollowUps += 1;
                }
              }
            }
            return acc;
          }, {})
        };

      } catch (err) {
        error.value = 'Failed to load dialing data.';
        console.error('Error fetching data:', err);
      } finally {
        loading.value = false;
      }
    };

    const printPDF = () => {
      const doc = new jsPDF();
      const tableColumn = ["Date", "Project", "Total Dials", "Total Leads", "Total Future", "Total Follow-ups"];
      if (showAssignee.value) tableColumn.splice(2, 0, "Assignee");

      const tableRows = [];

      for (const item of tableItems.value) {
        const rowData = [
          item.date,
          item.project,
          ...(showAssignee.value ? [item.assignee || 'N/A'] : []),
          item.totalDials.toString(),
          item.totalLeads.toString(),
          item.totalFuture.toString(),
          item.totalFollowUps.toString()
        ];
        tableRows.push(rowData);
      }

      doc.autoTable({ head: [tableColumn], body: tableRows, theme: 'grid' });
      doc.save('dialing_performance.pdf');
    };

    watch([selectedYear, selectedMonth], fetchDialingData);
    onMounted(fetchDialingData);

    return {
      dialStats,
      loading,
      error,
      selectedYear,
      selectedMonth,
      showAssignee,
      years,
      months,
      filteredDialStats,
      totalDials,
      totalRecords,
      fetchDialingData,
      printPDF,
      totalRecordsFetch,
      headers,
      tableItems,
      calculateTotal
    };
  }
};
</script>

<style>
.dialing-performance {
  font-family: Arial, sans-serif;
}

.v-data-footer {
  width: 100%;
  border-top: 1px solid rgba(0, 0, 0, 0.12);
  margin-top: 8px;
}

.v-data-footer td {
  padding: 8px;
  text-align: center;
}
</style>